'use client';

import { useEffect, useState } from 'react';
import { Contract, BrowserProvider, formatEther } from 'ethers';
import Link from 'next/link';

declare global {
  interface Window {
    ethereum?: any;
  }
}

export default function StakingPage() {
  const [amount, setAmount] = useState('100');
  const [isLoading, setIsLoading] = useState(false);
  const [address, setAddress] = useState('');

  useEffect(() => {
    const loadData = async () => {
      try {
        if (!window.ethereum) return;
        const provider = new BrowserProvider(window.ethereum);
        const signer = await provider.getSigner();
        const userAddress = await signer.getAddress();
        setAddress(userAddress);
      } catch (error) {
        console.error('Error:', error);
      }
    };
    loadData();
  }, []);

  const handleStake = async () => {
    if (!amount) return;
    setIsLoading(true);
    setTimeout(() => {
      alert('Stakea simulado exitosamente! 🎉');
      setIsLoading(false);
    }, 1500);
  };

  return (
    <div style={{ minHeight: '100vh', backgroundColor: 'var(--bg-dark)', color: 'var(--text-primary)' }}>
      <nav style={{
        borderBottom: '1px solid var(--border-color)',
        backdropFilter: 'blur(10px)',
        position: 'sticky',
        top: 0,
        zIndex: 50,
        backgroundColor: 'rgba(15, 15, 15, 0.8)'
      }}>
        <div style={{
          maxWidth: '1200px',
          margin: '0 auto',
          padding: '16px 24px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}>
          <Link href="/" style={{ textDecoration: 'none', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{
              width: '32px',
              height: '32px',
              background: 'linear-gradient(135deg, #00D4FF, #5514B4)',
              borderRadius: '8px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontSize: '18px'
            }}>
              ◆
            </div>
            <span style={{
              fontFamily: "'Montserrat', sans-serif",
              fontSize: '18px',
              fontWeight: '700',
              background: 'linear-gradient(90deg, #00D4FF, #f10050)',
              backgroundClip: 'text',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent'
            }}>
              NextiaToken
            </span>
          </Link>

          <div style={{ display: 'flex', gap: '32px' }}>
            <Link href="/" style={{ textDecoration: 'none', color: 'var(--text-secondary)', fontSize: '14px', fontWeight: '500' }}>
              Home
            </Link>
            <Link href="/staking" style={{ textDecoration: 'none', color: 'var(--color-secondary)', fontSize: '14px', fontWeight: '600' }}>
              Staking
            </Link>
            <Link href="/leaderboard" style={{ textDecoration: 'none', color: 'var(--text-secondary)', fontSize: '14px', fontWeight: '500' }}>
              Leaderboard
            </Link>
          </div>
        </div>
      </nav>

      <main style={{
        maxWidth: '600px',
        margin: '0 auto',
        padding: '60px 24px'
      }}>
        <div style={{ marginBottom: '48px' }}>
          <h1 style={{
            fontFamily: "'Montserrat', sans-serif",
            fontSize: '40px',
            fontWeight: '800',
            marginBottom: '12px',
            background: 'linear-gradient(90deg, #00D4FF, #f10050)',
            backgroundClip: 'text',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent'
          }}>
            Staking NXT
          </h1>
          <p style={{ color: 'var(--text-secondary)', fontSize: '15px' }}>
            Stakea tus tokens y gana rewards automáticos
          </p>
        </div>

        {address && (
          <div style={{
            background: 'var(--bg-card)',
            border: '1px solid var(--border-color)',
            borderRadius: '16px',
            padding: '16px',
            marginBottom: '24px'
          }}>
            <p style={{ fontSize: '12px', color: 'var(--text-muted)', marginBottom: '6px', textTransform: 'uppercase' }}>
              Wallet conectada
            </p>
            <p style={{ fontFamily: 'monospace', fontSize: '12px', color: 'var(--color-secondary)' }}>
              {address.slice(0, 10)}...{address.slice(-8)}
            </p>
          </div>
        )}

        <div style={{
          display: 'grid',
          gridTemplateColumns: '1fr 1fr 1fr',
          gap: '12px',
          marginBottom: '32px'
        }}>
          {[
            { label: 'Balance', value: '2000.0 NXT', color: 'var(--color-secondary)' },
            { label: 'Staked', value: '0.0 NXT', color: '#00DD00' },
            { label: 'Rewards', value: '0.0 NXT', color: '#FFDD00' }
          ].map((stat, i) => (
            <div key={i} style={{
              background: 'rgba(0, 212, 255, 0.05)',
              border: '1px solid var(--border-color)',
              borderRadius: '12px',
              padding: '16px',
              textAlign: 'center'
            }}>
              <p style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '6px', textTransform: 'uppercase' }}>
                {stat.label}
              </p>
              <p style={{ fontSize: '14px', fontWeight: '700', color: stat.color }}>
                {stat.value}
              </p>
            </div>
          ))}
        </div>

        <div style={{
          background: 'var(--bg-card)',
          border: '1px solid var(--border-color)',
          borderRadius: '16px',
          padding: '28px'
        }}>
          <p style={{
            fontSize: '13px',
            color: 'var(--text-muted)',
            marginBottom: '16px',
            textTransform: 'uppercase',
            fontWeight: '600'
          }}>
            Cantidad a Stakear
          </p>

          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            style={{
              width: '100%',
              background: 'rgba(0, 212, 255, 0.05)',
              border: '1px solid var(--border-color)',
              borderRadius: '12px',
              padding: '16px',
              color: 'var(--text-primary)',
              fontSize: '16px',
              marginBottom: '12px',
              fontFamily: 'inherit'
            }}
            placeholder="100"
          />

          <button
            onClick={() => setAmount('2000')}
            style={{
              background: 'transparent',
              color: 'var(--color-secondary)',
              border: '1px solid var(--border-color)',
              borderRadius: '8px',
              padding: '8px 16px',
              cursor: 'pointer',
              fontSize: '12px',
              fontWeight: '600',
              marginBottom: '24px'
            }}
          >
            Max
          </button>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
            <button
              onClick={handleStake}
              disabled={isLoading}
              style={{
                background: 'var(--color-primary)',
                color: 'white',
                border: 'none',
                borderRadius: '50px',
                padding: '14px',
                fontWeight: '600',
                cursor: isLoading ? 'not-allowed' : 'pointer',
                fontSize: '14px',
                opacity: isLoading ? 0.6 : 1
              }}
            >
              {isLoading ? 'Procesando...' : '✓ Stakear'}
            </button>

            <button
              style={{
                background: 'transparent',
                color: 'var(--text-primary)',
                border: '1px solid var(--border-color)',
                borderRadius: '50px',
                padding: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                fontSize: '14px'
              }}
            >
              ↓ Retirar
            </button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px', marginTop: '12px' }}>
            <button
              style={{
                background: 'transparent',
                color: 'var(--text-primary)',
                border: '1px solid var(--border-color)',
                borderRadius: '50px',
                padding: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                fontSize: '14px'
              }}
            >
              🎁 Reclamar
            </button>

            <button
              style={{
                background: 'transparent',
                color: 'var(--text-primary)',
                border: '1px solid var(--border-color)',
                borderRadius: '50px',
                padding: '14px',
                fontWeight: '600',
                cursor: 'pointer',
                fontSize: '14px'
              }}
            >
              🔄 Sacar todo
            </button>
          </div>
        </div>

        <div style={{
          textAlign: 'center',
          marginTop: '48px'
        }}>
          <Link href="/" style={{
            textDecoration: 'none',
            color: 'var(--color-secondary)',
            fontSize: '14px',
            fontWeight: '600'
          }}>
            ← Volver al Home
          </Link>
        </div>

        <div style={{
          textAlign: 'center',
          marginTop: '80px',
          paddingTop: '40px',
          borderTop: '1px solid var(--border-color)',
          color: 'var(--text-muted)',
          fontSize: '13px'
        }}>
          <p>Powered by NextiaToken • Sepolia Testnet</p>
        </div>
      </main>
    </div>
  );
}
